package com.pvphud;

import org.junit.Test;
import static org.junit.Assert.*;
import static com.pvphud.PvpHudPlugin.isNaturalBoostDecay;
import static com.pvphud.PvpHudPlugin.isNaturalDebuffRestore;

/**
 * Tests for the two static detection helpers in PvpHudPlugin that distinguish
 * natural stat-cycle ticks from potions, combat drains, and brews.
 *
 * Scenario legend:
 *   prev    = boosted level before this StatChanged event
 *   current = boosted level after (event.getBoostedLevel())
 *   base    = real level (event.getLevel())
 */
public class StatChangeDetectionTest
{
	// ── isNaturalBoostDecay ───────────────────────────────────────────────────

	@Test
	public void boostDecay_naturalMinusOne_detectsDecay()
	{
		// Boosted from 104 → 103, still above base 99.
		assertTrue(isNaturalBoostDecay(104, 103, 99));
	}

	@Test
	public void boostDecay_lastStep_toBase_detectsDecay()
	{
		// Boosted from 100 → 99 (exactly to base). current >= base, so still counts.
		assertTrue(isNaturalBoostDecay(100, 99, 99));
	}

	@Test
	public void boostDecay_potionBoost_ignored()
	{
		// Drinking a pot: 99 → 104 (large positive jump).
		assertFalse(isNaturalBoostDecay(99, 104, 99));
	}

	@Test
	public void boostDecay_largeDrop_combatDrain_ignored()
	{
		// Opponent uses stat-draining attack: 104 → 80 (drop > 1).
		assertFalse(isNaturalBoostDecay(104, 80, 99));
	}

	@Test
	public void boostDecay_dropsBelow_base_ignored()
	{
		// current (98) < base (99): combat drain into debuff territory, not boost decay.
		assertFalse(isNaturalBoostDecay(99, 98, 99));
	}

	@Test
	public void boostDecay_dropBelowBase_ignored()
	{
		// Going into debuff territory: 99 → 97 (two steps, combat drain).
		assertFalse(isNaturalBoostDecay(99, 97, 99));
	}

	// ── isNaturalDebuffRestore ────────────────────────────────────────────────

	@Test
	public void debuffRestore_naturalPlusOne_detectsRestore()
	{
		// Debuffed from 90 → 91, still below base 99.
		assertTrue(isNaturalDebuffRestore(90, 91, 99));
	}

	@Test
	public void debuffRestore_lastStep_toBase_detectsRestore()
	{
		// 98 → 99 (returning to base). current <= base, so still counts.
		assertTrue(isNaturalDebuffRestore(98, 99, 99));
	}

	@Test
	public void debuffRestore_crossesBase_ignored()
	{
		// current (100) > base (99): stat went above base (potion or regen), not a restore tick.
		assertFalse(isNaturalDebuffRestore(99, 100, 99));
	}

	@Test
	public void debuffRestore_brewLargeRestore_ignored()
	{
		// Saradomin brew restores multiple levels at once: 80 → 95 (large jump).
		assertFalse(isNaturalDebuffRestore(80, 95, 99));
	}

	@Test
	public void debuffRestore_statDrainBelow_ignored()
	{
		// Drain makes it worse: 90 → 85 (not a restore at all).
		assertFalse(isNaturalDebuffRestore(90, 85, 99));
	}

	// ── Divine potion interactions ────────────────────────────────────────────

	@Test
	public void divinePotion_wearOff_doesNotSyncBoostDecay()
	{
		// Divine super combat wears off: 118 → 99 (base=99, large multi-level drop).
		assertFalse(isNaturalBoostDecay(118, 99, 99));
	}

	@Test
	public void divinePotion_drink_doesNotSyncBoostDecay()
	{
		// Drinking divine super combat: 99 → 118 (large positive jump).
		assertFalse(isNaturalBoostDecay(99, 118, 99));
	}

	// ── Clock independence ────────────────────────────────────────────────────

	@Test
	public void boostDecay_doesNotTriggerDebuffRestore()
	{
		// A natural -1 above base must only fire the boost-decay clock.
		assertTrue(isNaturalBoostDecay(104, 103, 99));
		assertFalse(isNaturalDebuffRestore(104, 103, 99));
	}

	@Test
	public void debuffRestore_doesNotTriggerBoostDecay()
	{
		// A natural +1 below base must only fire the debuff-restore clock.
		assertTrue(isNaturalDebuffRestore(90, 91, 99));
		assertFalse(isNaturalBoostDecay(90, 91, 99));
	}
}

package com.pvphud;

import com.pvphud.state.BoostState;
import com.pvphud.state.PvpContextState;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Validates the login/world-hop rehydration contract at the state level.
 *
 * LOGGING_IN/HOPPING fires fullReset() → context.reset() → zone/combat state cleared.
 * LOGGED_IN fires updateEnvironment() which re-reads live varbits (tested in-game).
 * HUD visibility is computed on-demand via PvpHudPlugin.computeShouldShow() — not stored.
 */
public class LoginRehydrationTest
{
	// ── world hop clears fight data ───────────────────────────────────────────

	@Test
	public void worldHop_clearsFightSession()
	{
		PvpHudState state = new PvpHudState();
		state.beginSession("Bob", 100);
		state.getOpponent().setName("Bob");

		// HOPPING fires
		state.fullReset();

		assertNull("session cleared by hop", state.getCurrentSession());
		assertFalse("opponent not tracked after hop", state.getOpponent().isTracked());
	}

	@Test
	public void worldHop_clearsBoostState()
	{
		PvpHudState state = new PvpHudState();
		BoostState boosts = state.getBoosts();
		boosts.setAttackBoosted(118);
		boosts.setAttackReal(99);
		boosts.setStrengthBoosted(118);
		boosts.setStrengthReal(99);

		// HOPPING fires
		state.fullReset();

		assertEquals("attack boosted cleared by hop", 0, state.getBoosts().getAttackBoosted());
		assertEquals("attack real cleared by hop",    0, state.getBoosts().getAttackReal());
		assertEquals("strength boosted cleared by hop", 0, state.getBoosts().getStrengthBoosted());
	}

	@Test
	public void worldHop_thenRehydrate_correctFinalState()
	{
		// Full hop sequence: active fight → hop → session cleared
		PvpHudState state = new PvpHudState();
		state.beginSession("Alice", 50);
		state.getOpponent().setName("Alice");

		// HOPPING fires
		state.fullReset();

		// inPvpZone is re-seeded by updateEnvironment() (requires live Client; verified in-game)
		assertNull("no lingering fight session", state.getCurrentSession());
		assertFalse("opponent cleared", state.getOpponent().isTracked());
	}

	// ── context.reset() scope ─────────────────────────────────────────────────

	@Test
	public void contextReset_clearsPvpZoneAndWildLevel()
	{
		PvpContextState ctx = new PvpContextState();
		ctx.setInPvpZone(true);
		ctx.setWildernessLevel(34);
		ctx.setMultiCombat(true);

		ctx.reset();

		assertFalse(ctx.isInPvpZone());
		assertEquals(0, ctx.getWildernessLevel());
		assertFalse(ctx.isMultiCombat());
	}
}

package com.pvphud;

import com.pvphud.PvpHudPlugin;
import com.pvphud.state.SelfState;
import net.runelite.api.GraphicID;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.SpotanimID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Verifies that the freeze timer:
 *  - starts only from the confirmed "frozen" event (chat message),
 *  - is stored as startTick/endTick so remaining time is derived from the
 *    current tick rather than blindly decremented,
 *  - is NOT extended or reset by repeated ice impacts while already frozen,
 *  - uses RuneLite-matching base durations for all freeze spell types, and
 *  - is cleared by reset() / clearFreeze().
 */
public class SelfFreezeTimerTest
{
	// ── Base durations (must match PvpHudPlugin.freezeTicksForGraphic) ──────────

	@Test
	public void iceRush_baseDuration()
	{
		assertEquals(8, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_RUSH));
	}

	@Test
	public void iceBurst_baseDuration()
	{
		assertEquals(16, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BURST));
	}

	@Test
	public void iceBlitz_baseDuration()
	{
		assertEquals(24, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BLITZ));
	}

	@Test
	public void iceBarrage_baseDuration()
	{
		assertEquals(32, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BARRAGE));
	}

	@Test
	public void bind_baseDuration()
	{
		assertEquals(8, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.BIND_IMPACT));
	}

	@Test
	public void snare_baseDuration()
	{
		assertEquals(16, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.SNARE_IMPACT));
	}

	@Test
	public void entangle_baseDuration()
	{
		assertEquals(24, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.ENTANGLE_IMPACT));
	}

	@Test
	public void unknownGraphic_returnsZero()
	{
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(999));
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(0));
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(-1));
	}

	// ── applyFreeze — startTick/endTick semantics ─────────────────────────────

	@Test
	public void applyFreeze_setsTimerCorrectly()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 32, SpriteID.SPELL_ICE_BARRAGE);
		assertEquals(32, s.getFreezeTicksRemaining(10));
		assertEquals(1,  s.getFreezeTicksRemaining(41));
		assertEquals(0,  s.getFreezeTicksRemaining(42)); // exactly expired
	}

	@Test
	public void applyFreeze_remainingDerivesFromCurrentTick()
	{
		// Derived — not a counter: asking at different ticks gives correct answers
		// without needing any tick() / decrement calls.
		SelfState s = new SelfState();
		s.applyFreeze(0, 24, SpriteID.SPELL_ICE_BLITZ);
		assertEquals(24, s.getFreezeTicksRemaining(0));
		assertEquals(20, s.getFreezeTicksRemaining(4));
		assertEquals(12, s.getFreezeTicksRemaining(12));
		assertEquals(1,  s.getFreezeTicksRemaining(23));
		assertEquals(0,  s.getFreezeTicksRemaining(24));
	}

	@Test
	public void applyFreeze_pastEndTick_returnsZero()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 8, SpriteID.SPELL_ICE_RUSH);
		assertEquals(0, s.getFreezeTicksRemaining(100)); // well past expiry
	}

	// ── Repeated ice impacts while frozen must NOT extend the timer ──────────

	@Test
	public void repeatedImpact_doesNotExtendTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 32, SpriteID.SPELL_ICE_BARRAGE); // barrage at tick 10, ends at 42
		s.applyFreeze(15, 32, SpriteID.SPELL_ICE_BARRAGE); // second barrage at tick 15 — ignored
		// Timer must still end at tick 42, not 47
		assertEquals(27, s.getFreezeTicksRemaining(15));
		assertEquals(0,  s.getFreezeTicksRemaining(42));
	}

	@Test
	public void repeatedImpact_differentSpell_doesNotResetDuration()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE); // barrage at tick 0
		s.applyFreeze(5, 8, SpriteID.SPELL_ICE_RUSH);     // rush at tick 5 — ignored while frozen
		assertEquals(27, s.getFreezeTicksRemaining(5));    // 32 - 5 = 27, not 8
	}

	@Test
	public void newFreezeApplied_afterPreviousExpires()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 8, SpriteID.SPELL_ICE_RUSH);   // expires at tick 8
		s.applyFreeze(8, 32, SpriteID.SPELL_ICE_BARRAGE); // tick 8 = new freeze allowed
		assertEquals(32, s.getFreezeTicksRemaining(8));
	}

	// ── isFrozen ─────────────────────────────────────────────────────────────

	@Test
	public void isFrozen_trueWhileActive()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 16, SpriteID.SPELL_ICE_BURST);
		assertTrue(s.isFrozen(0));
		assertTrue(s.isFrozen(15));
	}

	@Test
	public void isFrozen_falseAtExpiry()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 16, SpriteID.SPELL_ICE_BURST);
		assertFalse(s.isFrozen(16));
		assertFalse(s.isFrozen(100));
	}

	@Test
	public void isFrozen_falseWhenNoFreezeApplied()
	{
		SelfState s = new SelfState();
		assertFalse(s.isFrozen(0));
		assertFalse(s.isFrozen(1000));
	}

	// ── Cancellation / reset ─────────────────────────────────────────────────

	@Test
	public void clearFreeze_cancelsActiveTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.clearFreeze();
		assertFalse(s.isFrozen(5));
		assertEquals(0, s.getFreezeTicksRemaining(5));
		assertEquals(0, s.getFreezeSpriteId());
	}

	@Test
	public void reset_clearsActiveFreezeTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.reset();
		assertFalse(s.isFrozen(10));
		assertEquals(0, s.getFreezeTicksRemaining(10));
		assertEquals(0, s.getFreezeSpriteId());
	}

	@Test
	public void afterClear_newFreezeCanBeApplied()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.clearFreeze();
		s.applyFreeze(5, 24, SpriteID.SPELL_ICE_BLITZ); // new freeze after cancellation
		assertEquals(24, s.getFreezeTicksRemaining(5));
	}

	// ── No freeze by default ─────────────────────────────────────────────────

	@Test
	public void noFreezeByDefault()
	{
		SelfState s = new SelfState();
		assertEquals(0, s.getFreezeTicksRemaining(0));
		assertEquals(0, s.getFreezeSpriteId());
		assertFalse(s.isFrozen(0));
	}

	// ── freezeStartTick — movement-thaw same-tick guard ──────────────────────

	@Test
	public void getFreezeStartTick_returnsApplyTick()
	{
		SelfState s = new SelfState();
		s.applyFreeze(42, 8, SpriteID.SPELL_BIND);
		assertEquals(42, s.getFreezeStartTick());
	}

	@Test
	public void getFreezeStartTick_clearedAfterClearFreeze()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 8, SpriteID.SPELL_BIND);
		s.clearFreeze();
		assertEquals(-1, s.getFreezeStartTick());
	}
}

package com.pvphud;

import com.pvphud.PvpHudState;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.EnumMap;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Verifies the gameframe-transition contracts:
 *
 *   - detectGameframe() correctly classifies Fixed, Resizable Classic, Resizable Modern.
 *   - Float positions are stored per-layout × per-gameframe; no cross-contamination.
 *   - Gameframe transitions mark layout geometry dirty but do NOT reset combat state.
 *   - Inventory Hug anchor is invalidated on gameframe change.
 *   - Horizontal Float reads live chatbox bounds, independent of the Chat Locked path.
 *   - Entering a float layout with no saved position does not inherit a locked anchor.
 *
 * All tests are deterministic and require no live RuneLite Client.
 */
public class GameframeTransitionTest
{
    // ── detectGameframe() ─────────────────────────────────────────────────────

    @Test
    public void detectGameframe_notResized_alwaysFixed()
    {
        // isResized=false must yield FIXED regardless of top-level interface ID
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL_OSRS_STRETCH));
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL_PRE_EOC));
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL));
    }

    @Test
    public void detectGameframe_resized_stretch_isResizableClassic()
    {
        assertEquals(GameframeType.RESIZABLE_CLASSIC,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL_OSRS_STRETCH));
    }

    @Test
    public void detectGameframe_resized_preEoc_isResizableModern()
    {
        assertEquals(GameframeType.RESIZABLE_MODERN,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL_PRE_EOC));
    }

    @Test
    public void detectGameframe_resized_unknownTopLevel_defaultsToClassic()
    {
        // An unknown top-level interface while resized defaults to RESIZABLE_CLASSIC
        assertEquals(GameframeType.RESIZABLE_CLASSIC,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL));
    }

    // ── Float position isolation across gameframes ────────────────────────────

    @Test
    public void fixedPosition_notInherited_byResizableModern()
    {
        // Saving a position for FIXED must not make it visible under RESIZABLE_MODERN
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        positions.put(GameframeType.FIXED, new Point(100, 200));

        assertNull("RESIZABLE_MODERN position is absent",
            positions.get(GameframeType.RESIZABLE_MODERN));
        assertNull("RESIZABLE_CLASSIC position is absent",
            positions.get(GameframeType.RESIZABLE_CLASSIC));
    }

    @Test
    public void fixedPosition_notInherited_byResizableClassic()
    {
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        positions.put(GameframeType.FIXED, new Point(50, 75));

        assertNull(positions.get(GameframeType.RESIZABLE_CLASSIC));
    }

    @Test
    public void savingResizableModernPosition_doesNotOverwriteFixed()
    {
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        Point fixedPt  = new Point(10, 20);
        Point modernPt = new Point(300, 400);
        positions.put(GameframeType.FIXED,            fixedPt);
        positions.put(GameframeType.RESIZABLE_MODERN, modernPt);

        assertEquals("FIXED position unchanged", fixedPt,  positions.get(GameframeType.FIXED));
        assertEquals("MODERN position correct",  modernPt, positions.get(GameframeType.RESIZABLE_MODERN));
    }

    @Test
    public void horizAndVertPositions_areStoredIndependently()
    {
        EnumMap<GameframeType, Point> horizPositions = new EnumMap<>(GameframeType.class);
        EnumMap<GameframeType, Point> vertPositions  = new EnumMap<>(GameframeType.class);

        Point hFixed = new Point(10, 20);
        Point vFixed = new Point(30, 40);
        horizPositions.put(GameframeType.FIXED, hFixed);
        vertPositions.put(GameframeType.FIXED,  vFixed);

        // Horiz-Fixed does not appear in vert map, and vice-versa
        assertEquals(hFixed, horizPositions.get(GameframeType.FIXED));
        assertEquals(vFixed, vertPositions.get(GameframeType.FIXED));
        assertNull("vert has no MODERN entry", vertPositions.get(GameframeType.RESIZABLE_MODERN));
        assertNull("horiz has no MODERN entry", horizPositions.get(GameframeType.RESIZABLE_MODERN));
    }

    @Test
    public void firstTimeFloat_noSavedPosition_returnsNull()
    {
        // When entering a float layout for the first time in a gameframe,
        // positions.get(gameframe) == null → setPreferredLocation(null).
        // This clears any locked-layout anchor so the float starts without inheriting it.
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        assertNull("no position saved yet for FIXED", positions.get(GameframeType.FIXED));
        assertNull("no position saved yet for CLASSIC", positions.get(GameframeType.RESIZABLE_CLASSIC));
        assertNull("no position saved yet for MODERN",  positions.get(GameframeType.RESIZABLE_MODERN));
    }

    // ── Combat state not reset on gameframe change ────────────────────────────

    @Test
    public void gameframeChange_preservesCombatState()
    {
        // Gameframe change must only touch layout geometry, never fullReset().
        PvpHudState state = new PvpHudState();
        state.beginSession("Target", 1000);
        state.getSelf().setCurrentHp(77);
        state.getContext().setInPvpZone(true);
        state.getEffects().setSpecEnergy(80);

        // What onGameframeChanged() does:
        state.getLayout().markDirty();
        // inventoryHugAnchorDirty = true (overlay internal, not accessible here)

        assertNotNull("session preserved", state.getCurrentSession());
        assertEquals("HP preserved", 77, state.getSelf().getCurrentHp());
        assertTrue("pvp zone preserved", state.getContext().isInPvpZone());
        assertEquals("spec preserved", 80, state.getEffects().getSpecEnergy());
    }

    @Test
    public void allTransitions_preserveCombatState()
    {
        GameframeType[][] transitions = {
            {GameframeType.FIXED, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.FIXED, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_MODERN, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.FIXED},
            {GameframeType.RESIZABLE_MODERN, GameframeType.FIXED},
        };
        for (GameframeType[] t : transitions)
        {
            PvpHudState state = new PvpHudState();
            state.beginSession("P", 0);
            state.getSelf().setCurrentHp(99);

            state.getLayout().markDirty(); // simulate gameframe transition

            assertNotNull("session preserved: " + t[0] + " -> " + t[1], state.getCurrentSession());
            assertEquals("HP preserved: " + t[0] + " -> " + t[1], 99, state.getSelf().getCurrentHp());
        }
    }

    // ── Layout dirty on gameframe change ─────────────────────────────────────

    @Test
    public void gameframeChange_marksLayoutDirty()
    {
        PvpHudState state = new PvpHudState();
        state.getLayout().setDirty(false);

        state.getLayout().markDirty(); // what onGameframeChanged() does

        assertTrue(state.getLayout().isDirty());
    }

    @Test
    public void allTransitions_allLayouts_markLayoutDirty()
    {
        GameframeType[][] transitions = {
            {GameframeType.FIXED, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.FIXED, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_MODERN, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.FIXED},
        };
        for (GameframeType[] t : transitions)
        {
            for (HudLayout layout : HudLayout.values())
            {
                PvpHudState state = new PvpHudState();
                state.getLayout().setDirty(false);

                state.getLayout().markDirty();

                assertTrue("layout dirty: " + layout + " " + t[0] + " -> " + t[1],
                    state.getLayout().isDirty());
            }
        }
    }

    // ── HorizFloat chatbox dimension independence ─────────────────────────────

    @Test
    public void horizFloat_staleChatboxBounds_replacedByFreshBounds()
    {
        // Simulate: Chat Locked in Fixed frame stored 519x165 in layout.
        // Gameframe switches to Resizable → layout marked dirty.
        // renderHorizontalFloat reads live chatbox → 754x168 → updates layout.
        PvpHudState state = new PvpHudState();
        state.getLayout().setChatboxBounds(new Rectangle(0, 0, 519, 165));
        state.getLayout().setDirty(false);

        // Gameframe change
        state.getLayout().markDirty();
        assertTrue("dirty after gameframe change", state.getLayout().isDirty());

        // Simulate renderHorizontalFloat reading live chatbox (getChatboxBounds())
        Rectangle liveBounds = new Rectangle(0, 0, 754, 168);
        if (!liveBounds.equals(state.getLayout().getChatboxBounds()))
        {
            state.getLayout().setChatboxBounds(new Rectangle(liveBounds));
            // computeHorizLayout would fire here (layout still dirty)
        }
        assertEquals("fresh width applied", 754, state.getLayout().getChatboxBounds().width);
        assertEquals("fresh height applied", 168, state.getLayout().getChatboxBounds().height);
    }

    @Test
    public void horizFloat_noChatLockedVisit_freshBoundsUsed()
    {
        // Contract: HorizFloat must NOT gate on layout.getChatboxBounds() being populated.
        // It reads getChatboxBounds() live each frame.
        // Proof by structure: if chatboxBounds is null (never visited Chat Locked),
        // renderHorizontalFloat falls back to (519, 200) and does NOT return null.
        PvpHudState state = new PvpHudState();
        assertNull("chatboxBounds not populated yet", state.getLayout().getChatboxBounds());

        // renderHorizontalFloat with null chatboxBounds would use fallback 519x200
        // (equivalent: currentChat == null → w=519, h=200 in the implementation)
        int expectedW = 519;
        int expectedH = 200;
        // Verify fallback values are positive (overlay can render)
