package com.pvphud;

import com.pvphud.state.PeriodicEffect;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Validates Menaphite Remedy two-icon state mechanics:
 *   - totalTicksRemaining: derived from varbit (value * 25); self-decrements each tick
 *   - nextProcTicks: reset to 25 on each varbit decrement; self-decrements each tick
 *   - Startup/mid-effect: nextProcTicks stays 0 until first observed proc
 *   - Effect expiry: both fields clear on varbit → 0
 *
 * Menaphite Remedy varbit:
 *   Starts at 20 on first drink. Decrements by 1 every 25 ticks (each prayer restore proc).
 *   Total duration = 20 * 25 = 500 ticks (~5 min). Proc period = 25 ticks (~15 s).
 */
public class MenaphiteRemedyTest
{
	// ── Fresh effect (player drinks Menaphite Remedy) ─────────────────────────

	@Test
	public void firstDrink_setsTotal_doesNotSetProc()
	{
		// Varbit 0 → 20 (first activation): total = 500 ticks, nextProcTicks stays 0
		// because we don't know where in the 25-tick cycle we are until a proc fires.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(20 * 25); // simulates varbit handler on 0→20
		// nextProcTicks intentionally NOT set (no decrement observed yet)

		assertEquals(500, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
		assertTrue(men.isActive());
	}

	// ── Proc fires (varbit decrements) ───────────────────────────────────────

	@Test
	public void proc_varbitDecrement_syncsNextProcTo25()
	{
		// Simulates varbit 20 → 19: a proc just fired, next restore is 25 ticks away.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(19 * 25); // 475 ticks
		men.setNextProcTicks(25);

		assertEquals(475, men.getTotalTicksRemaining());
		assertEquals(25, men.getNextProcTicks());
	}

	// ── Self-decrement between proc events ───────────────────────────────────

	@Test
	public void tick_decrementsTotal_andNextProc()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(475);
		men.setNextProcTicks(25);

		men.tick();

		assertEquals(474, men.getTotalTicksRemaining());
		assertEquals(24, men.getNextProcTicks());
	}

	@Test
	public void tick_24times_nextProcReachesOne()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(475);
		men.setNextProcTicks(25);

		for (int i = 0; i < 24; i++) men.tick();

		assertEquals(451, men.getTotalTicksRemaining());
		assertEquals(1, men.getNextProcTicks());
	}

	@Test
	public void tick_25times_nextProcReachesZero()
	{
		// After 25 ticks the proc fires and the varbit would decrement again.
		// nextProcTicks reaches 0; the varbit handler will reset it to 25.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(475);
		men.setNextProcTicks(25);

		for (int i = 0; i < 25; i++) men.tick();

		assertEquals(450, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
	}

	// ── Varbit resync corrects self-decrement drift ───────────────────────────

	@Test
	public void varbitResync_after25Ticks_alignsTotal()
	{
		// After 25 ticks of self-decrement, the varbit fires again and resets.
		// Both values should be consistent.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(19 * 25); // 475, varbit=19
		men.setNextProcTicks(25);

		for (int i = 0; i < 25; i++) men.tick(); // 25 self-decrements → 450, nextProc=0

		// varbit fires: 19 → 18; simulates what onVarbitChanged does
		men.setTotalTicksRemaining(18 * 25); // 450
		men.setNextProcTicks(25);

		assertEquals(450, men.getTotalTicksRemaining());
		assertEquals(25, men.getNextProcTicks());
	}

	// ── Startup mid-effect (nextProcTicks unknown) ────────────────────────────

	@Test
	public void midEffect_startup_nextProcTicksZero()
	{
		// Plugin starts while Menaphite Remedy is already active (varbit = 14).
		// We don't know where in the 25-tick cycle we are.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(14 * 25); // 350 ticks; nextProcTicks stays 0

		assertEquals(350, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
		// NXT entry should NOT be displayed (0 ticks → addTimedEffect skips it)
	}

	@Test
	public void midEffect_firstObservedProc_syncsNextProc()
	{
		// First observed varbit decrement (14 → 13) reveals proc fired; sync nextProcTicks.
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(14 * 25);

		// onVarbitChanged fires 14 → 13 (decrement observed while prevMenaphiteVarbit > 0)
		men.setTotalTicksRemaining(13 * 25);
		men.setNextProcTicks(25);

		assertEquals(325, men.getTotalTicksRemaining());
		assertEquals(25, men.getNextProcTicks());
	}

	// ── Effect expiry ─────────────────────────────────────────────────────────

	@Test
	public void effectExpiry_varbitToZero_clearsBothFields()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(25); // varbit = 1, one proc left
		men.setNextProcTicks(3);

		// varbit fires: 1 → 0 (effect ends)
		men.setTotalTicksRemaining(0);
		men.setNextProcTicks(0);

		assertEquals(0, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
		assertFalse("effect must not be active after varbit reaches 0", men.isActive());
	}

	@Test
	public void effectExpiry_naturalTickdown_doesNotGoNegative()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(1);
		men.setNextProcTicks(1);

		men.tick(); // both reach 0
		men.tick(); // already 0, must not go negative

		assertEquals(0, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
	}

	// ── isActive gate ─────────────────────────────────────────────────────────

	@Test
	public void isActive_trueWhenTotalPositive()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(1);
		assertTrue(men.isActive());
	}

	@Test
	public void isActive_falseWhenTotalZero()
	{
		PeriodicEffect men = new PeriodicEffect();
		assertFalse(men.isActive());
	}

	// ── reset() ───────────────────────────────────────────────────────────────

	@Test
	public void reset_clearsBothFields()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(300);
		men.setNextProcTicks(18);
		men.reset();

		assertEquals(0, men.getTotalTicksRemaining());
		assertEquals(0, men.getNextProcTicks());
		assertFalse(men.isActive());
	}

	// ── setTotalTicksRemaining clamps to zero ─────────────────────────────────

	@Test
	public void setTotal_negativeValue_clampedToZero()
	{
		PeriodicEffect men = new PeriodicEffect();
		men.setTotalTicksRemaining(-5);
		assertEquals(0, men.getTotalTicksRemaining());
	}
}

package com.pvphud;

import com.pvphud.state.CombatEvent;
import com.pvphud.state.CombatEventType;
import com.pvphud.state.PrayerEffect;
import com.pvphud.state.PvpFightSession;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Validates the state transitions for every fight-termination path:
 *   A. Stale timeout — 50-tick idle in onGameTick
 *   B. Opponent death — ratio==0 in pollOpponentHealth
 *   C. Local player death — HP==0 in onStatChanged
 *   D. Null-safe endSession (no session active)
 *   E. Session totals preserved on endSession
 */
public class FightLifecycleTest
{
	// A — stale timeout
	@Test
	public void staleTimeout_endSessionAndReset_leavesNoSession()
	{
		PvpHudState state = new PvpHudState();
		state.beginSession("Bob", 100);
		state.getOpponent().setName("Bob");

		// Simulate: session.isStale() → hudState.endSession() + opponent.reset()
		state.endSession();
		state.getOpponent().reset();

		assertNull("session must be null after stale termination", state.getCurrentSession());
		assertFalse("opponent must not be tracked after reset", state.getOpponent().isTracked());
	}

	@Test
	public void staleTimeout_isStale_firesAfter50Ticks()
	{
		PvpFightSession session = new PvpFightSession("Bob", 100);
		assertFalse("fresh session is not stale", session.isStale(100));
		assertFalse("49 ticks of idle is not stale", session.isStale(149));
		assertTrue("50 ticks of idle triggers stale", session.isStale(150));
		assertTrue("100 ticks of idle triggers stale", session.isStale(200));
	}

	@Test
	public void staleTimeout_combatRefreshes_idleClock()
	{
		PvpFightSession session = new PvpFightSession("Bob", 100);
		// A hit on tick 130 resets the idle clock to tick 130
		session.onOutgoingHit(
			new CombatEvent(CombatEventType.OUTGOING_HIT, 10, 0, 0,
				PrayerEffect.NONE, false, false, System.currentTimeMillis()),
			130);
		assertFalse("49 ticks after last combat is not stale", session.isStale(179));
		assertTrue("50 ticks after last combat is stale", session.isStale(180));
	}

	// B — opponent death
	@Test
	public void opponentDeath_endSessionAndReset_leavesNoSession()
	{
		PvpHudState state = new PvpHudState();
		state.beginSession("Alice", 50);
		state.getOpponent().setName("Alice");
		assertTrue("session exists before death", state.getOpponent().isTracked());

		// Simulate: ratio==0 → endSession() + opponent.reset()
		state.endSession();
		state.getOpponent().reset();

		assertNull("session null after opponent death", state.getCurrentSession());
		assertFalse("opponent not tracked after death reset", state.getOpponent().isTracked());
	}

	@Test
	public void opponentDeath_endSessionWithoutReset_wouldLeaveOpponentTracked()
	{
		// Confirms WHY the fix was necessary: endSession alone is insufficient.
		PvpHudState state = new PvpHudState();
		state.beginSession("Alice", 50);
		state.getOpponent().setName("Alice");

		state.endSession(); // no opponent.reset()

		assertNull("session is null", state.getCurrentSession());
		assertTrue("opponent still tracked (no reset called)", state.getOpponent().isTracked());
	}

	// C — local player death
	@Test
	public void localDeath_endSessionAndReset_leavesNoSession()
	{
		PvpHudState state = new PvpHudState();
		state.beginSession("Eve", 200);
		state.getOpponent().setName("Eve");

		// Simulate: HP==0 && prevHp>0 → endSession() + opponent.reset()
		state.endSession();
		state.getOpponent().reset();

		assertNull("session null after local death", state.getCurrentSession());
		assertFalse("opponent not tracked after local death", state.getOpponent().isTracked());
	}

	// D — null-safe endSession
	@Test
	public void endSession_whenNoSession_isNoop()
	{
		PvpHudState state = new PvpHudState();
		// No exception; sessionEndedMs stays at -1 (no session has ever ended).
		state.endSession();
		assertEquals(-1L, state.getSessionEndedMs());
		assertNull(state.getCurrentSession());
	}

	// E — totals preserved
	@Test
	public void sessionTotals_preservedAfterEndSession()
	{
		PvpHudState state = new PvpHudState();
		state.beginSession("Zed", 0);
		state.getOpponent().setName("Zed");

		PvpFightSession session = state.getCurrentSession();
		session.onOutgoingHit(
			new CombatEvent(CombatEventType.OUTGOING_HIT, 42, 0, 0,
				PrayerEffect.NONE, false, false, System.currentTimeMillis()),
			1);
		session.onIncomingHit(
			new CombatEvent(CombatEventType.INCOMING_HIT, 18, 0, 0,
				PrayerEffect.NONE, false, false, System.currentTimeMillis()),
			2);

		state.endSession();
		state.getOpponent().reset();

		assertEquals(42, state.getLastTotalOutgoing());
		assertEquals(18, state.getLastTotalIncoming());
		assertNull(state.getCurrentSession());
	}

	// Extra — terminated session.isStale() is always false (already ended)
	@Test
	public void terminatedSession_isNeverStale()
	{
		// isStale() guards against re-terminating. A session that was explicitly
		// terminated is never considered stale — the stale check is only for live sessions.
		PvpFightSession session = new PvpFightSession("Bob", 100);
		session.terminate();
		assertFalse("terminated session is not stale (already ended)", session.isStale(100));
		assertFalse("terminated session is not stale far in future", session.isStale(100_000));
	}
}

package com.pvphud;

import com.pvphud.state.SelfState;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Validates Tele Block timer decoding against Varbits.TELEBLOCK semantics.
 *
 * Raw varbit layout (mirrors RuneLite TimersAndBuffsPlugin):
 *   0        = TB not active, no immunity
 *   1..100   = post-TB reapplication immunity only; TB itself has expired
 *   101+     = TB active; remaining ticks = raw - 100
 *
 * Normal PvP TB:           raw 600 → 500 ticks (5:00)
 * Protect from Magic TB:   raw 350 → 250 ticks (2:30)
 * Boundary:                raw 101 → 1 tick
 * Expiry boundary:         raw 100 → 0 (timer disappears)
 * Post-TB immunity:        raw 1..99 → 0 (NOT shown as active TB)
 */
public class TeleBlockTimerTest
{
	// ── Decode function: raw → active TB ticks ────────────────────────────────

	@Test
	public void decode_raw600_returns500()
	{
		assertEquals(500, PvpHudPlugin.decodeTeleblockTicks(600));
	}

	@Test
	public void decode_raw350_returns250()
	{
		assertEquals(250, PvpHudPlugin.decodeTeleblockTicks(350));
	}

	@Test
	public void decode_raw101_returns1()
	{
		assertEquals(1, PvpHudPlugin.decodeTeleblockTicks(101));
	}

	@Test
	public void decode_raw100_returns0()
	{
		// Boundary: TB has just expired; immunity window starts
		assertEquals(0, PvpHudPlugin.decodeTeleblockTicks(100));
	}

	@Test
	public void decode_raw99_returns0()
	{
		// Deep in immunity window — must NOT be presented as active TB
		assertEquals(0, PvpHudPlugin.decodeTeleblockTicks(99));
	}

	@Test
	public void decode_raw1_returns0()
	{
		// Tail of immunity window
		assertEquals(0, PvpHudPlugin.decodeTeleblockTicks(1));
	}

	@Test
	public void decode_raw0_returns0()
	{
		// Fully inactive
		assertEquals(0, PvpHudPlugin.decodeTeleblockTicks(0));
	}

	// ── Login hydration uses decoded value ────────────────────────────────────

	@Test
	public void loginHydration_activeBlock_storesDecodedTicks()
	{
		// Simulates initSelfState() storing decodeTeleblockTicks(rawVarbit)
		SelfState self = new SelfState();
		int raw = 600;
		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(raw));

		assertEquals(500, self.getTeleBlockTicksRemaining());
	}

	@Test
	public void loginHydration_immunityOnly_storesZero()
	{
		// Raw 50 = post-TB immunity; must not show as active TB on login
		SelfState self = new SelfState();
		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(50));

		assertEquals(0, self.getTeleBlockTicksRemaining());
	}

	// ── VarbitChanged uses decoded value ──────────────────────────────────────

	@Test
	public void varbitChanged_activeBlock_storesDecodedTicks()
	{
		SelfState self = new SelfState();
		int incomingVarbit = 350; // protect-from-magic TB
		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(incomingVarbit));

		assertEquals(250, self.getTeleBlockTicksRemaining());
	}

	@Test
	public void varbitChanged_reachesExpiry_timerDisappears()
	{
		// Raw varbit counts down to 100 → decoded = 0 → timer clears
		SelfState self = new SelfState();
		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(101)); // 1 tick left
		assertEquals(1, self.getTeleBlockTicksRemaining());

		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(100)); // hits 0
		assertEquals(0, self.getTeleBlockTicksRemaining());
	}

	@Test
	public void varbitChanged_immunityPhase_timerStaysZero()
	{
		// After TB expires, varbit stays 1..100 (immunity). Decoded stays 0 throughout.
		SelfState self = new SelfState();
		for (int raw = 100; raw >= 1; raw--)
		{
			self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(raw));
			assertEquals("raw=" + raw + " is immunity, must decode to 0",
				0, self.getTeleBlockTicksRemaining());
		}
	}

	// ── No raw-value bleed-through ────────────────────────────────────────────

	@Test
	public void rawValueIsNeverStoredDirectly()
	{
		// If the bug existed, raw 600 would be stored and show ~6 min instead of ~5 min.
		SelfState self = new SelfState();
		self.setTeleBlockTicksRemaining(PvpHudPlugin.decodeTeleblockTicks(600));

		assertNotEquals("Raw value must not be stored directly",
			600, self.getTeleBlockTicksRemaining());
		assertEquals(500, self.getTeleBlockTicksRemaining());
	}
}

