package com.pvphud.state;

/**
 * State for a periodic timed effect (Menaphite Remedy, Prayer Regeneration potion).
 *
 * Two separate durations are tracked:
 *   totalTicksRemaining — full effect duration left (shown as "MEN 4:42")
 *   nextProcTicks       — countdown to the next individual proc (shown as "NEXT 0:12")
 *
 * nextProcTicks is self-decremented each tick. totalTicksRemaining is updated
 * from the server varbit each tick. Tasks 5 and 8 wire the specific mechanics.
 */
public class PeriodicEffect
{
	private int totalTicksRemaining;
	private int nextProcTicks;

	public boolean isActive()           { return totalTicksRemaining > 0; }
	public int getTotalTicksRemaining() { return totalTicksRemaining; }
	public int getNextProcTicks()       { return nextProcTicks; }

	public void setTotalTicksRemaining(int t) { totalTicksRemaining = Math.max(0, t); }
	public void setNextProcTicks(int t)       { nextProcTicks = Math.max(0, t); }

	public void tick()
	{
		if (totalTicksRemaining > 0) totalTicksRemaining--;
		if (nextProcTicks        > 0) nextProcTicks--;
	}

	public void reset()
	{
		totalTicksRemaining = 0;
		nextProcTicks       = 0;
	}
}

package com.pvphud.state;

/**
 * Tracks the time until the next natural boost-decay tick (-1 on a boosted stat),
 * accounting for the Preserve prayer using the same logic as RuneLite's
 * BoostsPlugin#getChangeDownTicks().
 *
 * How Preserve works in OSRS:
 *   The 100-tick decay cycle is divided into sections of ~25 ticks (15 s) each.
 *   If Preserve is active during the 4th section (ticks 75-100) the cycle extends
 *   to 125 ticks; if it remains active through the 5th section (100-125) the full
 *   150-tick cycle is granted.  Turning Preserve off after tick 75 forfeits the
 *   extension.  The 100-125 range is a "grace window" where Preserve can still
 *   activate if it was not on earlier.
 *
 * Usage:
 *   sync(currentTick)          — call when a natural exact -1 decay is observed
 *   update(currentTick, pres)  — call once per game tick from onGameTick
 *   getTicksRemaining()        — read from overlay (cached, no side-effects)
 *   isCalibrated()             — true after first sync
 */
public class BoostDecayClock
{
	private int     lastTick          = -1;
	private boolean preserveBeenActive = false;
	private int     ticksRemaining    = -1;

	public boolean isCalibrated()   { return lastTick != -1; }
	public int     getTicksRemaining() { return ticksRemaining; }

	/** Record the tick at which a natural exact -1 boost-decay event was observed. */
	public void sync(int currentTick)
	{
		lastTick           = currentTick;
		preserveBeenActive = false;
		ticksRemaining     = -1; // updated on the next update() call
	}

	/**
	 * Called once per game tick.  Mirrors RuneLite BoostsPlugin#getChangeDownTicks():
	 * computes remaining ticks accounting for Preserve and caches the result.
	 */
	public void update(int currentTick, boolean isPreserveActive)
	{
		if (lastTick == -1)
		{
			ticksRemaining = -1;
			return;
		}

		int elapsed = currentTick - lastTick;

		if ((isPreserveActive && (elapsed < 75 || preserveBeenActive)) || elapsed > 125)
		{
			preserveBeenActive = true;
			ticksRemaining     = 150 - elapsed;
			return;
		}

		preserveBeenActive = false;
		ticksRemaining = elapsed > 100 ? 125 - elapsed : 100 - elapsed;
	}

	public void reset()
	{
		lastTick           = -1;
		preserveBeenActive = false;
		ticksRemaining     = -1;
	}
}

package com.pvphud.state;

import lombok.Value;

/** Immutable snapshot of a single combat event. */
@Value
public class CombatEvent
{
	CombatEventType type;
	/** Primary damage value; 0 when not applicable. */
	int damage;
	/** Prayer points drained (e.g. Smite, Sara Strike, Clear Mind). 0 = none. */
	int prayerDrain;
	/** Prayer points restored by the effect (e.g. Clear Mind). 0 = none. */
	int prayerRestore;
	/** Which prayer-impact mechanic caused the drain/restore, or NONE. */
	PrayerEffect effectType;
	/** True when this hit was confirmed as a max-hit (CHANCE! event). */
	boolean chance;
	/** True when this hit landed same-tick as another hit in the opposite direction. */
	boolean stack;
	/** Wall-clock time of the event (System.currentTimeMillis). */
	long timestampMs;

	/** Convenience factory: plain outgoing hit with no special effects. */
	public static CombatEvent outgoing(int damage, long ts)
	{
		return new CombatEvent(CombatEventType.OUTGOING_HIT, damage,
			0, 0, PrayerEffect.NONE, false, false, ts);
	}

	/** Convenience factory: incoming hit with a prayer-impact effect. */
	public static CombatEvent incoming(int damage, int prayerDrain,
		int prayerRestore, PrayerEffect effect, long ts)
	{
		return new CombatEvent(CombatEventType.INCOMING_HIT, damage,
			prayerDrain, prayerRestore, effect, false, false, ts);
	}

	/** Convenience factory: plain incoming hit (no prayer impact). */
	public static CombatEvent incoming(int damage, long ts)
	{
		return incoming(damage, 0, 0, PrayerEffect.NONE, ts);
	}
}

package com.pvphud.state;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Maintains a rolling log of the most recent combat events (last 5). */
public class CombatEventState
{
	private static final int MAX_LOG = 5;

	private final ArrayDeque<CombatEvent> log = new ArrayDeque<>(MAX_LOG);

	public void post(CombatEvent event)
	{
		if (log.size() >= MAX_LOG)
		{
			log.pollLast();
		}
		log.addFirst(event);
	}

	/** Returns events newest-first; never null, may be empty. */
	public List<CombatEvent> getRecentEvents()
	{
		return Collections.unmodifiableList(new ArrayList<>(log));
	}

	public boolean hasEvents()
	{
		return !log.isEmpty();
	}

	public void clear()
	{
		log.clear();
	}
}

package com.pvphud.state;

import java.util.List;
import lombok.Getter;

/**
 * Lifecycle-managed snapshot of a single PvP encounter.
 *
 * A session begins when the local player first interacts with a named player.
 * It survives brief null interacting (movement, targeting flickers) and only
 * terminates on:
 *   - Opponent death (HP ratio → 0 via pollOpponentHealth)
 *   - Meaningful replacement by a different opponent after TIMEOUT_TICKS idle
 *   - Logout or world hop
 *   - Explicit eviction (plugin shutdown)
 *
 * Fight totals and the event log live here so they are not wiped by transient
 * InteractingChanged events.
 */
public class PvpFightSession
{
	/** Ticks with no combat in either direction before the session self-expires. ~30 s. */
	private static final int TIMEOUT_TICKS = 50;

	@Getter private final String opponentName;
	@Getter private final int    startTick;
	@Getter private int          lastCombatTick;

	private final CombatEventState events = new CombatEventState();

	/** Total damage this player dealt to the opponent this session. */
	@Getter private int totalOutgoing;
	/** Total damage this player received this session. */
	@Getter private int totalIncoming;

	/** True once terminate() has been called; immutable after that. */
	@Getter private boolean terminated;

	// ── STACK detection — multiple damage sources on the same actor in one tick ─
	// Outgoing stack: e.g. weapon hit + recoil ring on the opponent.
	// Incoming stack: e.g. opponent weapon hit + their vengeance on us.
	private int lastOutgoingHitTick = -1;
	private int lastIncomingHitTick = -1;

	public PvpFightSession(String opponentName, int startTick)
	{
		this.opponentName  = opponentName;
		this.startTick     = startTick;
		this.lastCombatTick = startTick;
	}

	/** Record an outgoing hit. Updates total, event log, and tracking state. */
	public void onOutgoingHit(CombatEvent event, int currentTick)
	{
		lastCombatTick      = currentTick;
		lastOutgoingHitTick = currentTick;
		totalOutgoing       += event.getDamage();
		events.post(event);
	}

	/** Record an incoming hit. Updates total, event log, and tracking state. */
	public void onIncomingHit(CombatEvent event, int currentTick)
	{
		lastCombatTick      = currentTick;
		lastIncomingHitTick = currentTick;
		totalIncoming       += event.getDamage();
		events.post(event);
	}

	/**
	 * Records an outgoing hit tick and returns true if a second (or later) outgoing
	 * hitsplat landed on the opponent in the same game tick — indicating a damage
	 * stack (e.g. weapon hit + recoil ring both resolving at once).
	 */
	public boolean recordAndCheckOutgoingStack(int tick)
	{
		boolean stack = (tick == lastOutgoingHitTick);
		lastOutgoingHitTick = tick;
		return stack;
	}

	/**
	 * Records an incoming hit tick and returns true if a second (or later) incoming
	 * hitsplat landed on the local player in the same game tick — indicating a
	 * damage stack (e.g. opponent weapon hit + their vengeance both resolving at once).
	 */
	public boolean recordAndCheckIncomingStack(int tick)
	{
		boolean stack = (tick == lastIncomingHitTick);
		lastIncomingHitTick = tick;
		return stack;
	}

	/** Recent events newest-first; never null. */
	public List<CombatEvent> getRecentEvents()
	{
		return events.getRecentEvents();
	}

	/**
	 * True when no combat has occurred for TIMEOUT_TICKS and the session has
	 * not been explicitly terminated. Checked each game tick by the plugin.
	 */
	public boolean isStale(int currentTick)
	{
		return !terminated && (currentTick - lastCombatTick) >= TIMEOUT_TICKS;
	}

	/** Permanently close this session. Safe to call multiple times. */
	public void terminate()
	{
		terminated = true;
	}
}

